import json
import time
from typing import List, Dict, TypedDict
from flask import Flask, request, Response, stream_with_context, render_template
from dotenv import load_dotenv

from langchain_core.tools import tool
from langchain_core.messages import HumanMessage, ToolMessage
from langchain_anthropic import ChatAnthropic
from langchain_openai import ChatOpenAI
from langgraph.graph import StateGraph, END
from pydantic import BaseModel, Field
from exa_py import Exa

# ==============================================================================
# 1. SETUP: Környezeti változók és kliensek betöltése
# ==============================================================================
load_dotenv()
app = Flask(__name__, template_folder='frontend', static_folder='frontend')

# API Kliensek inicializálása
try:
    # Supervisor és Synthesizer
    claude_client = ChatAnthropic(model="claude-3-5-sonnet-20240620", temperature=0.2)

    # Cognitive Agent (Data Extractor)
    cerebras_client = ChatOpenAI(
        model="gpt-oss-120b",
        openai_api_key=os.getenv("CEREBRAS_API_KEY"),
        openai_api_base="",
        temperature=0.0
    )

    # Hypothesis Agent és Real-time Search
    grok_client = ChatOpenAI(
        model="grok-4",
        openai_api_key=os.getenv("XAI_API_KEY"),
        openai_api_base="",
        temperature=0.1
    )

    # Perception Agent (Search)
    exa_client = Exa(api_key=os.getenv("EXA_API_KEY"))

    # Ellenőrzés
    if not all():
        raise ValueError("Egy vagy több API kulcs hiányzik a.env fájlból.")

except Exception as e:
    print(f"Hiba az API kliensek inicializálásakor: {e}")
    # Itt leállíthatnánk az alkalmazást, de a Flask kontextus miatt csak logolunk.
    # A stream endpoint majd kezeli a hibát.

# ==============================================================================
# 2. ESZKÖZÖK DEFINÍCIÓJA (TOOLS)
# ==============================================================================
@tool
def exa_search(query: str, num_results: int = 3, category: str = None) -> str:
    """Végez egy mély, szemantikus keresést az Exa API segítségével általános információgyűjtésre."""
    try:
        results = exa_client.search_and_contents(
            query, num_results=num_results, type="neural", category=category, text={"max_characters": 2000}
        )
        return json.dumps([{"url": res.url, "title": res.title, "content": res.text} for res in results.results])
    except Exception as e:
        return f"Hiba az Exa keresés során: {str(e)}"

@tool
def exa_find_similar(url: str, num_results: int = 2) -> str:
    """Egy adott URL-hez hasonló, releváns weboldalakat keres a téma mélyítéséhez."""
    try:
        results = exa_client.find_similar_and_contents(
            url, num_results=num_results, text={"max_characters": 2000}
        )
        return json.dumps([{"url": res.url, "title": res.title, "content": res.text} for res in results.results])
    except Exception as e:
        return f"Hiba a hasonló oldalak keresése során: {str(e)}"

@tool
def grok_realtime_search(query: str) -> str:
    """Valós idejű információkat keres a Grok segítségével, amely hozzáfér az X platform adataihoz."""
    try:
        messages = [HumanMessage(content=f"Keress valós idejű, friss információkat és közösségi média reakciókat a következő témában: {query}.")]
        response = grok_client.invoke(messages)
        return response.content
    except Exception as e:
        return f"Hiba a Grok valós idejű keresés során: {str(e)}"

tools = [exa_search, exa_find_similar, grok_realtime_search]
tool_map = {tool.name: tool for tool in tools}

# ==============================================================================
# 3. LANGGRAPH ÁLLAPOT, SÉMÁK ÉS ÁGENSEK DEFINÍCIÓJA
# ==============================================================================
class AgentState(TypedDict):
    user_query: str
    plan: List[str]
    tasks: List
    completed_tasks: List
    knowledge_graph: Dict
    hypotheses: List[str]
    final_report: str
    next_node: str

class Entity(BaseModel):
    name: str = Field(description="Az entitás neve (pl. 'Claude Sonnet', 'Grok 4').")
    type: str = Field(description="Az entitás típusa (pl. 'AI Model', 'Company', 'Technology').")

class Relationship(BaseModel):
    source: str = Field(description="A kapcsolat forrás entitásának neve.")
    target: str = Field(description="A kapcsolat cél entitásának neve.")
    relation: str = Field(description="A kapcsolat leírása (pl. 'developed_by', 'competes_with').")

class Knowledge(BaseModel):
    entities: List[Entity]
    relationships: List

def planning_node(state: AgentState):
    yield {"log": "A kutatási terv elkészítése...", "node": "supervisor", "status": "plan", "agent": "supervisor"}
    prompt = f"""
    Feladatod egy részletes, lépésről-lépésre haladó kutatási terv készítése a következő felhasználói kérés alapján: "{state['user_query']}"
    A tervnek 5-7 logikailag elkülönülő, végrehajtható feladatból kell állnia, amelyek lefedik a kutatás teljes folyamatát.
    A lépések tartalmazzanak általános keresést, mélyebb elemzést, valós idejű kontextus felmérését, és végül egy hipotézisgenerálási lépést.
    A válaszod csak a lépések listája legyen, minden lépés új sorban, kötőjellel kezdve.
    """
    response = claude_client.invoke([HumanMessage(content=prompt)])
    plan = [line.strip("- ") for line in response.content.split("\n") if line.strip()]
    tasks = [{"id": i, "description": task, "status": "pending"} for i, task in enumerate(plan)]
    return {"plan": plan, "tasks": tasks}

def perception_node(state: AgentState):
    task = next((t for t in state["tasks"] if t["status"] == "pending"), None)
    if not task: return {"next_node": "supervisor"}

    yield {"log": f"Feladat végrehajtása: '{task['description']}'", "node": "perception", "status": "perceive", "agent": "perception"}

    prompt = f"""Válassz egyet a rendelkezésre álló eszközök közül a következő feladat végrehajtásához: "{task['description']}"."""

    llm_with_tools = claude_client.bind_tools(tools)
    response = llm_with_tools.invoke([HumanMessage(content=prompt)])

    tool_results =
    if response.tool_calls:
        for call in response.tool_calls:
            try:
                result = tool_map[call["name"]].invoke(call["args"])
                tool_results.append({"tool": call["name"], "args": call["args"], "result": result})
                yield {"log": f"Eszközhívás: {call['name']}({json.dumps(call['args'])}) sikeres.", "node": "perception"}
            except Exception as e:
                tool_results.append({"tool": call["name"], "args": call["args"], "result": f"Hiba: {e}"})
                yield {"log": f"Eszközhívás hiba: {e}", "node": "ERROR"}
    else:
        yield {"log": "Az ágens nem választott eszközt. A feladat átugrása.", "node": "perception"}

    task["status"] = "completed"
    task["results"] = tool_results

    completed_tasks = state.get("completed_tasks",) + [task]
    updated_tasks = [t for t in state["tasks"] if t["id"]!= task["id"]]

    kpi_update = {"kpi": {"sources": len(completed_tasks)}}
    yield kpi_update

    return {"completed_tasks": completed_tasks, "tasks": updated_tasks}

def cognitive_node(state: AgentState):
    last_completed_task = state["completed_tasks"][-1]
    yield {"log": f"Eredmények feldolgozása: '{last_completed_task['description']}'", "node": "cognitive", "status": "cognize", "agent": "cognitive"}

    kg = state.get("knowledge_graph", {"entities":, "relationships":})

    for tool_result in last_completed_task.get("results",):
        content_to_process = str(tool_result.get("result", ""))
        if len(content_to_process) < 50: continue

        prompt = f"Elemezd a következő szöveget és nyerj ki belőle entitásokat és kapcsolatokat a megadott JSON séma szerint.\n\nSzöveg:\n---\n{content_to_process[:4000]}\n---"
        try:
            structured_llm = cerebras_client.with_structured_output(Knowledge)
            response = structured_llm.invoke(prompt)

            for entity in response.entities:
                if not any(e['name'].lower() == entity.name.lower() for e in kg['entities']):
                    kg['entities'].append({"name": entity.name, "type": entity.type})

            for rel in response.relationships:
                kg['relationships'].append({"source": rel.source, "target": rel.target, "relation": rel.relation})
            yield {"log": f"{len(response.entities)} entitás és {len(response.relationships)} kapcsolat kinyerve.", "node": "cognitive"}
        except Exception as e:
            yield {"log": f"Hiba az adatkinyerés során: {e}", "node": "ERROR"}

    kpi_update = {"kpi": {"entities": len(kg['entities'])}}
    yield kpi_update
    return {"knowledge_graph": kg}

def hypothesis_node(state: AgentState):
    yield {"log": "Új kutatási hipotézisek generálása.", "node": "hypothesis", "status": "hypothesis", "agent": "hypothesis"}
    kg_summary = json.dumps(state["knowledge_graph"], indent=2)[:4000]

    prompt = f"""
    Te egy briliáns tudományos stratéga vagy. A feladatod, hogy a jelenlegi tudásgráf alapján azonosíts tudásbeli hiányosságokat, ellentmondásokat vagy feltáratlan összefüggéseket, és ezek alapján fogalmazz meg 1-2 új, tesztelhető, provokatív hipotézist.
    Jelenlegi tudásgráf összefoglaló:
    ---
    {kg_summary}
    ---
    A válaszod csak a hipotézisek listája legyen, minden hipotézis új sorban.
    """
    try:
        response = grok_client.invoke([HumanMessage(content=prompt)])
        new_hypotheses = [h.strip() for h in response.content.split("\n") if h.strip() and h.strip()!= "-"]

        current_hypotheses = state.get("hypotheses",) + new_hypotheses

        kpi_update = {"kpi": {"hypotheses": len(current_hypotheses)}}
        yield kpi_update
        return {"hypotheses": current_hypotheses}
    except Exception as e:
        yield {"log": f"Hiba a hipotézis generálás során: {e}", "node": "ERROR"}
        return {}

def synthesis_node(state: AgentState):
    yield {"log": "A végső jelentés elkészítése.", "node": "synthesis", "status": "synthesize", "agent": "synthesis"}
    kg_summary = json.dumps(state["knowledge_graph"], indent=2)
    hypotheses = "\n- ".join(state.get("hypotheses", ["Nincsenek generált hipotézisek."]))

    prompt = f"""
    Készíts egy részletes, legalább 800 szavas, jól strukturált kutatási jelentést a következő felhasználói kérés alapján: "{state['user_query']}"
    Használd fel az alábbi összegyűjtött tudásgráfot és a generált hipotéziseket.
    A jelentés legyen objektív, tényszerű és használjon Markdown formázást.
    Hivatkozz a forrásokra, ahol csak lehetséges (a tudásgráf nem tartalmaz URL-eket, de említsd meg a felhasznált entitásokat és kapcsolataikat).
    A jelentés szerkezete: 1. Bevezetés, 2. Főbb Eredmények, 3. Új Hipotézisek és Jövőbeli Kutatási Irányok, 4. Összegzés.

    Tudásgráf:
    ---
    {kg_summary}
    ---

    Generált hipotézisek:
    ---
    - {hypotheses}
    ---
    """
    response = claude_client.invoke([HumanMessage(content=prompt)])
    return {"final_report": response.content}

def supervisor_node(state: AgentState):
    yield {"log": "Supervisor döntési pont.", "node": "supervisor", "agent": "supervisor"}
    if not state.get("plan"):
        return {"next_node": "plan"}

    if state.get("tasks"):
        pending_task_desc = state["tasks"]["description"].lower()
        if "hipotézis" in pending_task_desc or "elemezd a tudásgráfot" in pending_task_desc:
             return {"next_node": "hypothesis"}
        else:
            return {"next_node": "perceive"}

    if not state.get("final_report"):
        return {"next_node": "synthesize"}

    return {"next_node": "end"}

# ==============================================================================
# 4. LANGGRAPH GRAF ÖSSZEÁLLÍTÁSA
# ==============================================================================
workflow = StateGraph(AgentState)

workflow.add_node("plan", planning_node)
workflow.add_node("perceive", perception_node)
workflow.add_node("cognize", cognitive_node)
workflow.add_node("hypothesis", hypothesis_node)
workflow.add_node("synthesize", synthesis_node)
workflow.add_node("supervisor", supervisor_node)

workflow.set_entry_point("supervisor")

workflow.add_conditional_edges(
    "supervisor",
    lambda state: state["next_node"],
    {"plan": "plan", "perceive": "perceive", "hypothesis": "hypothesis", "synthesize": "synthesize", "end": END}
)

workflow.add_edge("plan", "supervisor")
workflow.add_edge("perceive", "cognize")
workflow.add_edge("cognize", "supervisor")
workflow.add_edge("hypothesis", "supervisor")
workflow.add_edge("synthesize", END)

graph = workflow.compile()

# ==============================================================================
# 5. FLASK ALKALMAZÁS ÉS VÉGPONTOK
# ==============================================================================
@app.route('/')
def index():
    return render_template('index.html')

@app.route('/start-research')
def start_research():
    query = request.args.get('query')
    if not query:
        return Response(json.dumps({"error": "Nincs megadva lekérdezés."}), mimetype='application/json')

    def generate():
        initial_state = {"user_query": query, "knowledge_graph": {"entities":, "relationships":}}
        try:
            # API kliensek ellenőrzése minden kérésnél
            if not all():
                raise ConnectionError("Egy vagy több API kulcs hiányzik. Ellenőrizd a.env fájlt.")

            final_state = None
            for state_chunk in graph.stream(initial_state, stream_mode="values"):
                for node, output in state_chunk.items():
                    if isinstance(output, dict):
                        # Log és státusz üzenetek küldése
                        if "log" in output:
                            message = {"log": output["log"], "node": output.get("node", "SYSTEM")}
                            if "status" in output: message["status"] = output["status"]
                            if "agent" in output: message["agent"] = output["agent"]
                            yield f"data: {json.dumps(message)}\n\n"
                        # KPI frissítések küldése
                        if "kpi" in output:
                            yield f"data: {json.dumps({'kpi': output['kpi']})}\n\n"
                final_state = state_chunk

            # Az utolsó állapotból kinyerjük a végső riportot
            last_node_output = list(final_state.values())[-1]
            final_report = last_node_output.get("final_report", "A jelentés generálása nem sikerült.")
            final_kg = last_node_output.get("knowledge_graph", {})

            yield f"data: {json.dumps({'report': final_report, 'knowledge_graph': final_kg})}\n\n"

        except Exception as e:
            error_message = f"Végzetes hiba a munkafolyamat során: {str(e)}"
            app.logger.error(error_message, exc_info=True)
            yield f"data: {json.dumps({'error': error_message, 'node': 'ERROR'})}\n\n"

    return Response(stream_with_context(generate()), mimetype='text/event-stream')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
